import { Knob } from "@/components/audio/elements/knob";

const MARKS = [
  { label: "0", value: 0 },
  25,
  50,
  75,
  { label: "100", value: 100 },
];

export function KnobDemo() {
  return (
    <Knob
      aria-label="Level"
      defaultValue={50}
      marks={MARKS}
      max={100}
      min={0}
      size="lg"
      step={1}
    />
  );
}
